import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernels for fused operations
linear_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void linear_relu_kernel(const float* input, const float* weight, const float* bias, float* output,
                                   int batch_size, int in_features, int out_features) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < batch_size && col < out_features) {
        float sum = 0.0f;
        for (int k = 0; k < in_features; ++k) {
            sum += input[row * in_features + k] * weight[col * in_features + k];
        }
        sum += bias[col];
        output[row * out_features + col] = fmaxf(sum, 0.0f);
    }
}

torch::Tensor linear_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    int batch_size = input.size(0);
    int in_features = input.size(1);
    int out_features = weight.size(0);

    auto output = torch::zeros({batch_size, out_features}, torch::device(torch::kCUDA).dtype(torch::kFloat32));

    dim3 block(16, 16);
    dim3 grid((out_features + block.x - 1) / block.x, (batch_size + block.y - 1) / block.y);

    linear_relu_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );

    return output;
}
"""

relu_maxpool_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void relu_maxpool2d_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int input_height,
    int input_width,
    int kernel_size,
    int stride,
    int padding,
    int output_height,
    int output_width
) {
    int n = blockIdx.x;
    int c = blockIdx.y;
    int h_out = blockIdx.z / output_width;
    int w_out = blockIdx.z % output_width;

    if (n >= batch_size || c >= channels || h_out >= output_height || w_out >= output_width) {
        return;
    }

    int h_start = h_out * stride - padding;
    int w_start = w_out * stride - padding;
    int h_end = h_start + kernel_size;
    int w_end = w_start + kernel_size;

    h_start = max(h_start, 0);
    w_start = max(w_start, 0);
    h_end = min(h_end, input_height);
    w_end = min(w_end, input_width);

    float max_val = -FLT_MAX;
    for (int h = h_start; h < h_end; ++h) {
        for (int w = w_start; w < w_end; ++w) {
            int idx = n * channels * input_height * input_width + c * input_height * input_width + h * input_width + w;
            float val = input[idx];
            val = fmaxf(val, 0.0f);
            if (val > max_val) {
                max_val = val;
            }
        }
    }
    int out_idx = n * channels * output_height * output_width + c * output_height * output_width + h_out * output_width + w_out;
    output[out_idx] = max_val;
}

torch::Tensor relu_maxpool2d_cuda(
    torch::Tensor input,
    int kernel_size,
    int stride,
    int padding
) {
    int batch_size = input.size(0);
    int channels = input.size(1);
    int input_height = input.size(2);
    int input_width = input.size(3);

    int output_height = (input_height + 2 * padding - kernel_size) / stride + 1;
    int output_width = (input_width + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch_size, channels, output_height, output_width}, input.options());

    dim3 grid(batch_size, channels, output_height * output_width);
    relu_maxpool2d_kernel<<<grid, 1>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        input_height,
        input_width,
        kernel_size,
        stride,
        padding,
        output_height,
        output_width
    );

    return output;
}
"""

# Load CUDA extensions
linear_relu = load_inline(
    name='linear_relu',
    cpp_sources="torch::Tensor linear_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);",
    cuda_sources=linear_relu_source,
    functions=['linear_relu_cuda'],
    verbose=False
)

relu_maxpool = load_inline(
    name='relu_maxpool',
    cpp_sources="torch::Tensor relu_maxpool2d_cuda(torch::Tensor input, int kernel_size, int stride, int padding);",
    cuda_sources=relu_maxpool_source,
    functions=['relu_maxpool2d_cuda'],
    verbose=False
)

# Custom fused modules
class LinearReLU(nn.Module):
    def __init__(self, in_features, out_features):
        super().__init__()
        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, nonlinearity='relu')
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return linear_relu.linear_relu_cuda(x, self.weight, self.bias)

class FusedReLUMaxPool2d(nn.Module):
    def __init__(self, kernel_size, stride, padding=0):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

    def forward(self, x):
        return relu_maxpool.relu_maxpool2d_cuda(x, self.kernel_size, self.stride, self.padding)

# Optimized model
class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()

        self.features = nn.Sequential(
            # Block 1
            nn.Conv2d(3, 64, kernel_size=3, padding=1),
            nn.ReLU(inplace=True),
            nn.Conv2d(64, 64, kernel_size=3, padding=1),
            FusedReLUMaxPool2d(kernel_size=2, stride=2),

            # Block 2
            nn.Conv2d(64, 128, kernel_size=3, padding=1),
            nn.ReLU(inplace=True),
            nn.Conv2d(128, 128, kernel_size=3, padding=1),
            FusedReLUMaxPool2d(kernel_size=2, stride=2),

            # Block 3
            nn.Conv2d(128, 256, kernel_size=3, padding=1),
            nn.ReLU(inplace=True),
            nn.Conv2d(256, 256, kernel_size=3, padding=1),
            nn.ReLU(inplace=True),
            nn.Conv2d(256, 256, kernel_size=3, padding=1),
            FusedReLUMaxPool2d(kernel_size=2, stride=2),

            # Block 4
            nn.Conv2d(256, 512, kernel_size=3, padding=1),
            nn.ReLU(inplace=True),
            nn.Conv2d(512, 512, kernel_size=3, padding=1),
            nn.ReLU(inplace=True),
            nn.Conv2d(512, 512, kernel_size=3, padding=1),
            FusedReLUMaxPool2d(kernel_size=2, stride=2),

            # Block 5
            nn.Conv2d(512, 512, kernel_size=3, padding=1),
            nn.ReLU(inplace=True),
            nn.Conv2d(512, 512, kernel_size=3, padding=1),
            nn.ReLU(inplace=True),
            nn.Conv2d(512, 512, kernel_size=3, padding=1),
            FusedReLUMaxPool2d(kernel_size=2, stride=2)
        )

        self.classifier = nn.Sequential(
            LinearReLU(512 * 7 * 7, 4096),
            nn.Dropout(p=0.0),
            LinearReLU(4096, 4096),
            nn.Dropout(p=0.0),
            nn.Linear(4096, num_classes)
        )

    def forward(self, x):
        x = self.features(x)
        x = torch.flatten(x, 1)
        x = self.classifier(x)
        return x
